export function parseLocation(): UrlState {
  const url = new URL(window.location.href)
  const network: Network = url.searchParams.get('network') === 'testnet' ? 'testnet' : 'mainnet'
  const embed = url.searchParams.get('embed') === '1'
  const compareRaw = url.searchParams.get('compare')
  const compare = compareRaw && isValidTxHash(compareRaw) ? compareRaw : null
  const base = { network, path: [], address: null, simulate: false, learn: false, cell: null, view: 'flow' as FlowView, embed, compare }

  if (url.pathname === '/learn') return { ...base, learn: true }
  if (url.pathname === '/simulate') return { ...base, simulate: true }

  const addrMatch = url.pathname.match(/^\/address\/(ck[bt]1[0-9a-z]+)$/i)
  if (addrMatch?.[1] && looksLikeAddress(addrMatch[1])) return { ...base, address: addrMatch[1] }

  const txMatch = url.pathname.match(/^\/tx\/(0x[0-9a-fA-F]{64})$/)
  const hash = txMatch?.[1]
  if (!hash || !isValidTxHash(hash)) return base
  const viewParam = url.searchParams.get('view')
  const view: FlowView = viewParam === 'owners' ? 'owners' : viewParam === 'sankey' ? 'sankey' : 'flow'
  const cell = url.searchParams.get('cell')
  return { ...base, path: [hash], view,

export function buildUrl(
  network: Network,
  hash: string | null,
  address?: string | null,
  simulate?: boolean,
  learn?: boolean,
  cell?: string | null,
  view?: FlowView,
  embed?: boolean,
  compare?: string | null,
): string {
  // The learn page is a static primer that never touches the chain, so it does
  // not carry a network in its URL. The selection still rides in the history
  // state (see App), so leaving the lesson returns you to your chosen network.
  if (learn) return '/learn'
  const query = `?network=${network}`
  if (simulate) return `/simulate${query}`
  if (address) return `/address/${address}${query}`
  if (!hash) return `/${query}`
  const extra =
    `${view === 'owners' ? '&view=owners' : view === 'sankey' ? '&view=sankey' : ''}` +
    `${cell ? `&cell=${cell}` : ''}` +
    `${embed ? '&embed=1' : ''}` +
    `${compare && isValidTxHash(compare) ? `&compare=${compare}` : ''}`
  return `/tx/${hash}${query}${extra}`
}

